def parse_gencost(self, gencost_data):
    """Parse generator cost data: [type, startup, shutdown, n, c(n), ..., c(0)]"""
    self.gencost = {}
    for i, row in enumerate(gencost_data):
        if len(row) >= 5:
            n = int(row[3])
            costs = list(row[4:4+n])
            self.gencost[i] = {
                'type': int(row[0]),
                'startup': float(row[1]),
                'shutdown': float(row[2]),
                'n': n,
                'c': costs
            }

            # Handle polynomial cost (type 2)
            # For type 2, costs are typically ordered as [c0, c1, c2, ...] or [c_highest, ..., c_lowest]
            if self.gencost[i]['type'] == 2:
                if n == 2:
                    # Linear: c1*P + c0
                    self.gencost[i]['c0'] = float(costs[0]) if len(costs) > 0 else 0.0
                    self.gencost[i]['c1'] = float(costs[1]) if len(costs) > 1 else 0.0
                    self.gencost[i]['c2'] = 0.0
                elif n >= 3:
                    # Quadratic: c2*P^2 + c1*P + c0
                    # Typically the last coefficient is c0
                    self.gencost[i]['c2'] = float(costs[0]) if len(costs) > 0 else 0.0
                    self.gencost[i]['c1'] = float(costs[1]) if len(costs) > 1 else 0.0
                    self.gencost[i]['c0'] = float(costs[2]) if len(costs) > 2 else 0.0
                else:
                    self.gencost[i]['c2'] = 0.0
                    self.gencost[i]['c1'] = 0.0
                    self.gencost[i]['c0'] = 0.0

